import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";
import { chromium } from "/Users/me/workspace/estate/production-evidence-49f845d0dece/browser-tools/node_modules/playwright/index.mjs";

const sourceRoot = process.argv[2], pinPath = process.argv[3];
assert.ok(sourceRoot && pinPath, "Pass the reviewed source root and source-pin file");
const output = "/Users/me/hamon-longwater-practice-review-71826f7aa69e/history-composition";
const pins = JSON.parse(await readFile(pinPath, "utf8"));
assert.equal(pins.target, "2451ec6fa29d10fa8bac53b59faf95c69fb9951c");
const sha = b => createHash("sha256").update(b).digest("hex");
const blob = b => createHash("sha1").update("blob " + b.length + "\0").update(b).digest("hex");
async function verify() {
  const result = [];
  for (const pin of pins.files) {
    const bytes = await readFile(sourceRoot + "/" + pin.path);
    assert.equal(bytes.length, pin.bytes, pin.path + " byte length");
    assert.equal(blob(bytes), pin.git_blob, pin.path + " reviewed Git blob");
    result.push({ path: pin.path, bytes: bytes.length, sha256: sha(bytes), git_blob: blob(bytes) });
  }
  return result;
}
async function liveView(page) {
  return page.evaluate(() => ({
    summary: document.querySelector("#state-summary").textContent,
    selected: [...document.querySelectorAll("#playfield [data-cell]")].map(e => e.getAttribute("aria-pressed")),
    readings: [0, 1, 2].map(i => document.querySelector("#cell-" + i + "-readings").textContent),
    event: document.querySelector("#event-notes").textContent,
    report: [...document.querySelectorAll("#report-lines li")].map(e => e.textContent),
    journal: document.querySelector("#watch-journal").innerHTML,
    save_status: document.querySelector("#watch-save-status").textContent,
    storage: Object.fromEntries(Object.keys(localStorage).sort().map(k => [k, localStorage.getItem(k)])),
  }));
}
async function choiceView(page) {
  return page.evaluate(() => ({
    root_hidden: document.querySelector("#watch-choice").hidden,
    panel: document.querySelector("#watch-choice").innerHTML,
    details_open: document.querySelector("#choice-details").open,
    tide: document.querySelector("#choice-tide").value,
    action: document.querySelector("#choice-action").value,
    cell: document.querySelector("#choice-cell").value,
    result_hidden: document.querySelector("#choice-result").hidden,
    result_tide: document.querySelector("#choice-result").dataset.tide,
  }));
}
async function assertComparison(page, before, played, alternative) {
  for (const key of ["freshwater", "seedPacks"]) {
    assert.deepEqual(await page.locator('#choice-result [data-resource="' + key + '"] td').allTextContents(),
      [before[key], played[key], alternative[key]].map(String), "complete resource columns: " + key);
  }
  for (const original of before.cells) {
    const actual = played.cells.find(c => c.id === original.id);
    const other = alternative.cells.find(c => c.id === original.id);
    for (const key of ["depth", "salinity", "oxygen", "biomass", "shade"]) {
      const selector = '#choice-result [data-cell-id="' + original.id + '"] [data-reading="' + key + '"] td';
      assert.deepEqual(await page.locator(selector).allTextContents(),
        [original[key], actual[key], other[key]].map(String), original.id + "/" + key + " native columns");
    }
  }
  for (const [kind, state] of [["played", played], ["alternative", alternative]]) {
    const root = '#choice-result [data-kind="' + kind + '"]';
    assert.deepEqual(await page.locator(root + " .choice-notes li").allTextContents(), state.report.lines);
    assert.equal(await page.locator(root + " .choice-event").textContent(), state.report.event.name);
    assert.equal(await page.locator(root + " .choice-event-note").textContent(), state.report.event.note);
  }
}
const receipt = {
  schema: "longwater-practice-history-independent/1",
  reviewer: "estate-71826f7aa69e/coordination",
  target: pins.target,
  draft_tree: pins.draft_tree,
  criterion: "criterion.json",
  case_count: 1,
  started_at: new Date().toISOString(),
  boundary: "Actual composed DOM and shipped WASM in a fresh isolated browser. No product source, native return value or historical model is substituted. A Node native session supplies only independent expected history and alternative readings.",
  checks: [],
};
let browser, context, server, control, alternativeControl;
const pageErrors = [];
await mkdir(output, { recursive: true });
try {
  const cutBytes = await readFile(sourceRoot + "/../evidence/source-cut.json");
  assert.equal(sha(cutBytes), pins.source_cut_sha256);
  receipt.source_cut_sha256 = sha(cutBytes);
  receipt.source_before = await verify();
  const { serve } = await import(pathToFileURL(sourceRoot + "/tests/server.mjs").href);
  const { initSync, BrowserSession } = await import(pathToFileURL(sourceRoot + "/pkg/longwater_web.js").href);
  const wasm = await readFile(sourceRoot + "/pkg/longwater_web_bg.wasm");
  assert.equal(sha(wasm), "76deec059601613d588f4685444d407da81b3339f7cf7bdaf1bd1a13b285dae2");
  initSync({ module: wasm });
  control = new BrowserSession();
  const turns = [
    { action: "gate", cell: "heart", index: 1 },
    { action: "seed", cell: "south", index: 2 },
    { action: "shade", cell: "north", index: 0 },
  ];
  const history = [control.snapshot_json()];
  for (const t of turns) history.push(control.take_turn(t.action, t.cell));
  alternativeControl = new BrowserSession();
  assert.equal(alternativeControl.take_turn("gate", "heart"), history[1]);
  const alternativeRaw = alternativeControl.take_turn("gate", "north");
  const fixture = { turns, history, alternative: { tide: 2, action: "gate", cell: "north", snapshot: alternativeRaw } };
  const fixtureBytes = JSON.stringify(fixture, null, 2) + "\n";
  await writeFile(output + "/native-control-fixture.json", fixtureBytes);
  receipt.fixture = { path: "native-control-fixture.json", sha256: sha(fixtureBytes), bytes: Buffer.byteLength(fixtureBytes) };

  server = await serve();
  browser = await chromium.launch({ headless: true, executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" });
  context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  await context.addInitScript(() => {
    window.__reviewSaveWrites = [];
    const original = Storage.prototype.setItem;
    Storage.prototype.setItem = function(key, value) {
      window.__reviewSaveWrites.push(String(key));
      return Reflect.apply(original, this, [key, value]);
    };
  });
  const page = await context.newPage();
  page.setDefaultTimeout(7000);
  page.on("pageerror", error => pageErrors.push(error.message));
  await page.goto(server.url + "/");
  await page.waitForFunction(() => !document.querySelector("#practice-open").disabled);
  assert.equal(await page.locator("#startup-error").isVisible(), false);
  receipt.runtime = { node: process.version, chrome: browser.version(), headless: true, url: server.url, wasm_bytes: wasm.length };
  for (const turn of turns) {
    await page.locator('#playfield [data-cell="' + turn.index + '"]').click();
    await page.locator('#playfield [data-action="' + turn.action + '"]').click();
  }
  const original = await liveView(page);
  const saved = original.storage["longwater.watch.v1"];
  assert.equal(JSON.parse(saved).snapshot, history[3]);
  assert.equal(await page.locator("#journal-entries > li").count(), 3);
  await page.locator("#choice-details > summary").click();
  await page.locator("#choice-tide").selectOption("1");
  await page.locator("#choice-cell").selectOption("south");
  await page.locator("#choice-action").selectOption("shade");
  await page.locator("#choice-run").press("Enter");
  assert.equal(await page.locator("#choice-result").evaluate(e => e.hidden), false);
  assert.equal(await page.locator("#choice-result").getAttribute("data-tide"), "1");
  assert.match(await page.locator(".choice-alternative-label").textContent(), /Shade.*South Reach/);
  assert.match(await page.locator("#choice-status").textContent(), /Historical comparison ready/);
  assert.deepEqual(await liveView(page), original);
  const historical = await choiceView(page);
  const writesBefore = await page.evaluate(() => window.__reviewSaveWrites.length);

  await page.locator("#practice-open").click();
  assert.match(await page.locator("#practice-summary").textContent(), /Practice tide 0 \/ 14/);
  await page.locator('[data-practice-cell="2"]').click();
  await page.locator('[data-practice-action="gate"]').click();
  await page.locator('[data-practice-cell="1"]').click();
  await page.locator('[data-practice-action="seed"]').press("Enter");
  assert.match(await page.locator("#practice-summary").textContent(), /Practice tide 2 \/ 14/);
  assert.deepEqual(await choiceView(page), historical, "populated historical result stays byte-exact behind practice");
  assert.deepEqual(await liveView(page), original, "practice leaves active native state, journal and save exact");
  assert.equal(await page.evaluate(() => window.__reviewSaveWrites.length), writesBefore);
  await page.locator("[data-practice-close]").click();
  assert.equal(await page.locator("#practice-watch").evaluate(e => e.open), false);
  assert.equal(await page.locator("#practice-open").evaluate(e => e === document.activeElement), true);
  assert.deepEqual(await choiceView(page), historical, "closing practice retains the populated historical form/result");
  assert.deepEqual(await liveView(page), original);
  receipt.checks.push({
    name: "populated historical comparison survives two accepted practice tides and close",
    passed: true,
    historical_panel_sha256: sha(JSON.stringify(historical)),
    historical_tide: 1,
    historical_alternative: "shade/south",
    accepted_practice_tides: 2,
    source_live_tides: 3,
    live_save_sha256: sha(saved),
    additional_storage_writes: 0,
    focus_restored_to_practice_entry: true,
  });

  await page.locator("#choice-tide").selectOption("2");
  await page.locator("#choice-cell").selectOption("north");
  await page.locator("#choice-action").selectOption("gate");
  await page.locator("#choice-run").press("Enter");
  assert.equal(await page.locator("#choice-result").getAttribute("data-tide"), "2");
  assert.match(await page.locator(".choice-alternative-label").textContent(), /Gate.*North Bank/);
  assert.match(await page.locator("#choice-status").textContent(), /Historical comparison ready/);
  const alternative = JSON.parse(alternativeRaw);
  await assertComparison(page, JSON.parse(history[1]), JSON.parse(history[2]), alternative);
  assert.equal(await page.locator("#choice-result h3").evaluate(e => e === document.activeElement), true);
  assert.deepEqual(await liveView(page), original);
  assert.equal(await page.evaluate(() => window.__reviewSaveWrites.length), writesBefore);
  assert.deepEqual(pageErrors, []);
  receipt.checks.push({
    name: "historical controls remain usable and all displayed native columns/reports match independent replay",
    passed: true,
    compared_tide: 2,
    alternative: "gate/north",
    independent_prefix: "gate/heart",
    native_alternative_snapshot_bytes: Buffer.byteLength(alternativeRaw),
    native_alternative_sha256: sha(alternativeRaw),
    exact_numeric_columns: 51,
    complete_played_and_alternative_reports_equal: true,
    result_heading_focused: true,
    active_watch_and_saved_bytes_unchanged: true,
    additional_storage_writes: 0,
  });
  receipt.source_after = await verify();
  receipt.source_unchanged = JSON.stringify(receipt.source_before) === JSON.stringify(receipt.source_after);
  receipt.status = "passed";
} catch (error) {
  receipt.status = "failed";
  receipt.error = String(error);
  receipt.stack = error.stack;
} finally {
  control?.free();
  alternativeControl?.free();
  await context?.close();
  await browser?.close();
  await server?.close();
  receipt.page_errors = pageErrors;
  receipt.completed_at = new Date().toISOString();
  const body = JSON.stringify(receipt, null, 2) + "\n";
  console.log(JSON.stringify(receipt));
  await writeFile(output + "/receiving.json", body);
  process.exitCode = receipt.status === "passed" ? 0 : 1;
}
